const stored = $json;

if (!stored.id || !stored.created_at) {
  return [{
    json: {
      success: false,
      statusCode: 503,
      error: {
        code: 'PERSISTENCE_ERROR',
        message: 'Lead was analyzed but could not be saved.',
      },
    },
  }];
}

return [{
  json: {
    success: true,
    statusCode: 200,
    lead_id: stored.id,
    created_at: stored.created_at,
    lead: {
      name: stored.name,
      email: stored.email,
      company: stored.company,
      message: stored.message,
      budget: Number(stored.budget),
    },
    analysis: {
      category: stored.category,
      priority: stored.priority,
      lead_score: stored.lead_score,
      short_summary: stored.short_summary,
      recommended_action: stored.recommended_action,
    },
  },
}];

const sheetsResult = $json;
const persisted = $('Sanitize Persistence Result').item.json;
const sheetsFailed = Boolean(sheetsResult.error) || sheetsResult.success === false;

if (sheetsFailed || !persisted?.success || !persisted?.created_at) {
  return [{
    json: {
      success: false,
      statusCode: 503,
      error: {
        code: 'PERSISTENCE_ERROR',
        message: 'Lead was analyzed but could not be fully persisted.',
      },
    },
  }];
}

return [{ json: persisted }];

const persisted = $json;
const parts = String(persisted.lead.name ?? '').trim().split(/\s+/).filter(Boolean);
const firstname = parts.shift() ?? '';
const lastname = parts.join(' ');

return [{
  json: {
    ...persisted,
    crmContact: {
      email: persisted.lead.email,
      firstname,
      lastname,
      company: persisted.lead.company,
    },
  },
}];

const response = $json;
const prepared = $('Prepare HubSpot Contact').item.json;
const statusCode = Number(response.statusCode ?? 0);

const crmError = () => [{
  json: {
    success: false,
    statusCode: 503,
    error: {
      code: 'CRM_ERROR',
      message: 'Lead was persisted but could not be synchronized with CRM.',
    },
  },
}];

if (statusCode < 200 || statusCode >= 300) {
  return crmError();
}

const result = response.body;
if (!result || typeof result !== 'object' || !Array.isArray(result.results)) {
  return crmError();
}

if (result.results.length === 0) {
  return [{
    json: {
      ...prepared,
      crmContact: { ...prepared.crmContact, action: 'create' },
    },
  }];
}

const contactId = result.results[0]?.id;
if (!contactId) {
  return crmError();
}

return [{
  json: {
    ...prepared,
    crmContact: {
      ...prepared.crmContact,
      action: 'update',
      contactId: String(contactId),
    },
  },
}];

const response = $json;
const prepared = $('Determine HubSpot Contact Path').item.json;
const statusCode = Number(response.statusCode ?? 0);
const result = response.body;

if (statusCode < 200 || statusCode >= 300 || !result || typeof result !== 'object' || !result.id) {
  return [{
    json: {
      success: false,
      statusCode: 503,
      error: {
        code: 'CRM_ERROR',
        message: 'Lead was persisted but could not be synchronized with CRM.',
      },
    },
  }];
}

const { crmContact, ...workflowData } = prepared;
return [{ json: workflowData }];

const envelope = $json && typeof $json === 'object' ? $json : {};
const headers = envelope.headers && typeof envelope.headers === 'object' ? envelope.headers : {};
const input = envelope.body && typeof envelope.body === 'object' && !Array.isArray(envelope.body) ? envelope.body : {};
const rawKey = headers['idempotency-key'];

const normalizeText = (value) => typeof value === 'string' ? value.trim() : value;
const normalizeBudget = (value) => {
  if (typeof value === 'number') return value;
  if (typeof value === 'string' && value.trim() !== '') {
    const numeric = Number(value);
    if (Number.isFinite(numeric)) return numeric;
  }
  return normalizeText(value);
};
const body = {
  name: normalizeText(input.name),
  email: normalizeText(input.email),
  company: normalizeText(input.company),
  message: normalizeText(input.message),
  budget: normalizeBudget(input.budget),
};
const canonicalPayload = JSON.stringify([
  ['name', body.name ?? null],
  ['email', body.email ?? null],
  ['company', body.company ?? null],
  ['message', body.message ?? null],
  ['budget', body.budget ?? null],
]);

if (rawKey === undefined || rawKey === null) {
  return [{ json: { body, idempotency_mode: 'absent', idempotency_key: null, canonical_payload: canonicalPayload } }];
}

const keyPattern = /^[A-Za-z0-9][A-Za-z0-9._~:/+=-]{0,127}$/;
if (typeof rawKey !== 'string' || !keyPattern.test(rawKey)) {
  return [{ json: { body, idempotency_mode: 'invalid', idempotency_key: null, canonical_payload: canonicalPayload, statusCode: 400, error: { code: 'INVALID_IDEMPOTENCY_KEY', message: 'Idempotency-Key is invalid.' } } }];
}

return [{ json: { body, idempotency_mode: 'valid', idempotency_key: rawKey, canonical_payload: canonicalPayload } }];

const row = $json && typeof $json === 'object' ? $json : {};
const failure = (code, message, statusCode = 409) => [{ json: { idempotency_action: 'error', statusCode, error: { code, message } } }];

if (row.error) return failure('IDEMPOTENCY_ERROR', 'The request could not be safely accepted.', 503);
if (row.outcome === 'owner' && typeof row.claim_token === 'string' && typeof row.request_fingerprint === 'string') {
  return [{ json: { idempotency_action: 'process', claim_token: row.claim_token, request_fingerprint: row.request_fingerprint } }];
}
if (row.outcome === 'in_progress') return failure('REQUEST_IN_PROGRESS', 'A request with this Idempotency-Key is already processing.');
if (row.outcome === 'conflict') return failure('IDEMPOTENCY_CONFLICT', 'This Idempotency-Key was already used with a different request.');
if (row.outcome === 'recovery_required') return failure('RECONCILIATION_REQUIRED', 'The original request requires manual reconciliation and cannot be retried automatically.');
if (row.outcome === 'failed') return failure('REQUEST_FAILED', 'The original request did not complete and cannot be retried automatically.');

if (row.outcome === 'completed') {
  let payload = row.response_payload;
  if (typeof payload === 'string') {
    try { payload = JSON.parse(payload); } catch { return failure('IDEMPOTENCY_ERROR', 'The saved response could not be replayed safely.', 503); }
  }
  const priorities = new Set(['high', 'medium', 'low']);
  const analysis = payload && payload.analysis;
  const valid = payload && payload.success === true && priorities.has(payload.route) && typeof payload.message === 'string' && analysis && typeof analysis === 'object' && typeof analysis.category === 'string' && priorities.has(analysis.priority) && Number.isInteger(analysis.lead_score) && analysis.lead_score >= 0 && analysis.lead_score <= 100 && typeof analysis.short_summary === 'string' && typeof analysis.recommended_action === 'string';
  if (!valid) return failure('IDEMPOTENCY_ERROR', 'The saved response could not be replayed safely.', 503);
  return [{ json: { idempotency_action: 'replay', public_response: { success: true, route: payload.route, message: payload.message, analysis: { category: analysis.category, priority: analysis.priority, lead_score: analysis.lead_score, short_summary: analysis.short_summary, recommended_action: analysis.recommended_action } } } }];
}

return failure('IDEMPOTENCY_ERROR', 'The request could not be safely accepted.', 503);

const data = $json;
const context = $('Prepare Idempotency Context').item.json;
return [{ json: { ...data, public_response: { success: true, route: data.route, message: data.message, analysis: data.analysis }, idempotency_required: context.idempotency_mode === 'valid' } }];

const result = $json;
if (result.error || result.idempotency_completed !== true) {
  return [{ json: { completion_action: 'error', statusCode: 503, error: { code: 'IDEMPOTENCY_STATE_ERROR', message: 'The request completed but its replay state could not be recorded.' } } }];
}
const prepared = $('Prepare Idempotency Completion').item.json.public_response;
return [{ json: { completion_action: 'success', route: prepared.route, message: prepared.message, analysis: prepared.analysis } }];

const context = $('Prepare Idempotency Context').item.json;
const data = $json;
const statusCode = Number.isInteger(data.statusCode) ? data.statusCode : 503;
const error = data.error && typeof data.error.code === 'string' && typeof data.error.message === 'string' ? { code: data.error.code, message: data.error.message } : { code: 'WORKFLOW_ERROR', message: 'The request could not be completed.' };
return [{ json: { statusCode, error, idempotency_required: context.idempotency_mode === 'valid' } }];

